        public async Task<IEnumerable<GoodsIssue>> GetByProductIdAsync(Guid productId)
        {
            return await _dbSet
                .Where(i => i.ProductId == productId)
                .Include(i => i.Product)
                .Include(i => i.Customer)
                .ToListAsync();
        }

