        /// </summary>
        public async Task<IEnumerable<GoodsIssue>> GetByDateRangeAsync(DateTime startDate, DateTime endDate)
        {
            return await _dbSet
                .Where(i => i.IssueDate >= startDate && i.IssueDate <= endDate)
                .Include(i => i.Product)
                .Include(i => i.Customer)
                .OrderBy(i => i.IssueDate)
                .ToListAsync();
        }

