        /// </summary>
        public async Task<GoodsIssue?> GetIssueWithDetailsAsync(int issueId)
        {
            return await _dbSet
                .Include(i => i.Product)
                .Include(i => i.Customer)
                .Include(i => i.Warehouse)
                .FirstOrDefaultAsync(i => i.IssueId == issueId);
        }

