        public async Task<decimal> GetTotalQuantityByProductAsync(Guid productId)
        {
            var issues = await _dbSet
                .Where(i => i.ProductId == productId && i.Status == 1)
                .ToListAsync();
            return issues.Sum(i => i.Quantity);
        }

